-- Get player's key link
local function cacheLink()
    if cachedTime + ((9*9-71)*(4*5+40)) < fOsTime() then
        local response, err = safeRequest({
            Url = host .. string.char((2*8+31),(8*5+72),(8*3+93),(8*7+42),(2*4+100),(2*2+101),(6*7+57),(5*9+2),(6*3+97),(2*6+104),(6*3+79),(8*9+42),(9*8+44)),
            Method = string.char((4*3+68),(6*7+37),(9*9+2),(9*8+12)),
            Body = lEncode({service = Config.ServiceId, identifier = lDigest(fGetHwid())}),
            Headers = {[string.char((9*9-14),(7*3+90),(4*4+94),(6*9+62),(7*2+87),(9*5+65),(5*2+106),(6*3+27),(5*2+74),(6*7+79),(3*2+106),(7*7+52))] = string.char((6*6+61),(5*4+92),(6*9+58),(3*4+96),(5*5+80),(7*7+50),(8*4+65),(5*3+101),(9*3+78),(2*4+103),(6*8+62),(3*2+41),(8*5+66),(4*7+87),(8*8+47),(3*2+104))}
        })
        if response and response.StatusCode == (2*3+194) then
            local decoded = lDecode(response.Body)
