-- Verify key on input
local function redeemKey(key)
    local nonce = generateNonce()
    local body = {identifier = lDigest(fGetHwid()), key = key}
    if useNonce then body.nonce = nonce end

    local response, err = safeRequest({
        Url = host .. string.char((6*5+17),(4*4+96),(6*8+69),(3*6+80),(5*7+73),(4*4+89),(6*2+87),(4*2+39),(5*6+84),(3*7+80),(4*9+64),(8*4+69),(4*3+89),(5*2+99),(8*7-9)) .. fToString(Config.ServiceId),
        Method = string.char((4*8+48),(9*9-2),(7*6+41),(8*8+20)),
        Body = lEncode(body),
        Headers = {[string.char((7*4+39),(2*8+95),(5*6+80),(5*3+101),(5*6+71),(8*5+70),(8*3+92),(8*7-11),(4*9+48),(8*2+105),(8*4+80),(3*9+74))] = string.char((3*6+79),(9*5+67),(4*8+80),(7*3+87),(7*8+49),(2*4+91),(3*6+79),(2*8+100),(3*8+81),(4*2+103),(8*9+38),(9*4+11),(7*9+43),(9*6+61),(9*8+39),(8*4+78))}
    })

    if response and response.StatusCode == (2*4+192) then
        local decoded = lDecode(response.Body)
        if decoded.success and decoded.data.valid then
            if useNonce then
                if decoded.data.hash == lDigest(string.char((6*3+98),(5*8+74),(9*6+63),(3*6+83)) .. string.char((4*9+9)) .. nonce .. string.char((4*3+33)) .. Config.PlatoSecret) then
                    if writefile then writefile(Config.KeyFileName, key) end
                    return true, string.char((3*4+71),(9*2+99),(9*8+27),(3*5+84),(7*3+80),(8*7+59),(4*6+91))
                end
                return false, string.char((4*6+49),(3*2+104),(5*5+91),(4*3+89),(4*4+87),(9*9+33),(9*7+42),(2*8+100),(3*3+112),(2*4+24),(8*3+43),(8*7+48),(3*9+74),(6*6+63),(6*6+71),(6*5+2),(3*3+61),(3*3+88),(9*6+51),(5*2+98),(4*3+89),(9*4+64))
            end
            if writefile then writefile(Config.KeyFileName, key) end
            return true, string.char((3*5+68),(8*6+69),(8*9+27),(8*7+43),(5*7+66),(6*6+79),(2*7+101))
        end
        return false, decoded.message or string.char((2*5+63),(6*2+98),(4*8+86),(6*9+43),(9*2+90),(9*6+51),(5*8+60),(3*8+8),(6*2+63),(5*8+61),(2*2+117))
    end
    return false, err or string.char((9*4+47),(7*7+52),(6*7+72),(4*7+90),(6*3+83),(7*6+72),(7*4+4),(3*4+57),(9*7+51),(5*6+84),(5*6+81),(6*2+102))
end

