local function StartMainScript()
    local player = game:GetService(string.char((7*9+17),(5*3+93),(3*8+73),(5*3+106),(6*5+71),(8*5+74),(2*8+99))).LocalPlayer
    local pGui = player:WaitForChild(string.char((5*4+60),(6*9+54),(7*8+41),(5*7+86),(6*8+53),(5*6+84),(8*6+23),(8*7+61),(5*5+80)))

    -- Destroy old GUI if it exists
    if pGui:FindFirstChild(Config.OldGuiName) then
        pGui[Config.OldGuiName]:Destroy()
        task.wait(0.1)
    end

    -- Set secret global variable to bypass main script protection
    _G[Config.Secret] = true

    -- Execute main script
    loadstring(game:HttpGet(Config.MainScriptURL))()
end

local function CreateGUI()
    local player = game:GetService(string.char((9*2+62),(5*6+78),(6*3+79),(3*9+94),(6*8+53),(5*4+94),(7*6+73))).LocalPlayer
