    -- Auto Check Saved Key
    if isfile and isfile(Config.KeyFileName) then
        local savedKey = readfile(Config.KeyFileName)
        if savedKey ~= string.char() then
            Status.Text = string.char((6*4+46),(5*8+71),(6*7+75),(2*5+100),(8*3+76),(5*7-3),(4*2+107),(6*3+79),(4*4+102),(7*2+87),(4*3+88),(8*6-16),(9*3+80),(6*9+47),(7*6+79),(3*6+26),(2*4+24),(5*7+83),(6*3+83),(7*7+65),(7*8+49),(7*6+60),(2*9+103),(3*4+93),(8*6+62),(2*7+89),(9*6-8),(7*7-3),(3*6+28))
            task.spawn(function()
                local success, msg = redeemKey(savedKey)
                if success then
                    Status.Text = string.char((8*9-7),(4*8+85),(5*7+81),(4*4+95),(3*3+36),(2*6+96),(6*5+81),(7*7+54),(7*4+77),(4*3+98),(5*3+17),(4*8+83),(8*2+101),(6*6+63),(3*3+90),(3*5+86),(2*6+103),(6*4+91),(6*8-15))
                    Status.TextColor3 = Color3.fromRGB(0, (9*8+183), (3*8+76))
                    task.wait(0.5)
                    ScreenGui:Destroy()
                    StartMainScript()
                else
                    Status.Text = string.char((7*5+48),(5*2+87),(3*3+109),(5*2+91),(7*7+51),(9*7-31),(7*4+79),(7*4+73),(3*2+115),(3*8+8),(3*6+83),(9*3+93),(5*8+72),(8*4+73),(4*6+90),(5*5+76),(7*6+58),(8*4+0),(9*9+30),(8*5+74),(2*6+20),(9*6+51),(8*5+70),(3*8+94),(3*5+82),(2*9+90),(5*8+65),(5*7+65),(6*2+34))
                    Status.TextColor3 = Color3.fromRGB((3*2+249), (3*8+126), 0)
                end
            end)
        end
    end
end

